import { TestingModule } from '@nestjs/testing';
import { MikroORM } from '@mikro-orm/core';
import { createIntegrationTestModule, cleanDatabase } from './setup';
import { UserSession } from '../../src/entities/user-session.entity';
import { buildUserSession } from '../factories/user-session.factory';
import { User } from '../../src/entities/user.entity';
import { buildUser } from '../factories/user.factory';

describe('UserSession Relationships', () => {
  let module: TestingModule;
  let orm: MikroORM;
  let userId: string;

  beforeAll(async () => {
    module = await createIntegrationTestModule();
    orm = module.get(MikroORM);
  });

  beforeEach(async () => {
    const em = orm.em.fork();
    const userEntity = em.create(
      User,
      buildUser(),
    );
    await em.persistAndFlush(userEntity);
    userId = userEntity.id;
  });

  afterEach(async () => {
    await cleanDatabase(orm);
  });

  afterAll(async () => {
    await module.close();
  });

  describe('belongs_to User', () => {
    it('persists user reference', async () => {
      const em = orm.em.fork();
      const data = buildUserSession({ user: userId });
      const saved = em.create(UserSession, data);
      await em.persistAndFlush(saved);
      await em.populate(saved, ['user']);
      expect(saved.user.id).toBe(userId);
    });

    it('loads parent via relation', async () => {
      const em = orm.em.fork();
      const data = buildUserSession({ user: userId });
      const saved = em.create(UserSession, data);
      await em.persistAndFlush(saved);
      const loaded = await em.findOne(
        UserSession,
        { id: saved.id },
        { populate: ['user'] },
      );
      expect(loaded).not.toBeNull();
      expect(loaded!.user).toBeDefined();
      expect(loaded!.user.id).toBe(userId);
    });

    it('rejects entity without required user', async () => {
      const em = orm.em.fork();
      const data = buildUserSession({ user: undefined as unknown as string });
      const row = em.create(UserSession, data);
      await expect(em.persistAndFlush(row)).rejects.toThrow();
    });
  });
});
